/*
 * A369321  T(n,k) is the number of length-n weak ascent sequences (prefixed
 *          with a zero) with k weak ascents, triangle read by rows.
 * https://oeis.org/A369321
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the T(row, col) entry of the weak‑ascent‑sequence
 *            triangle read row by row (offset 0). T(n,k) counts length‑n weak
 *            ascent sequences prefixed with 0 having k weak ascents. The
 *            sequence is generated by a dynamic‑programming construction for
 *            the triangle
 * Range:     u8 n <= 25, u16 n <= 51, u32 n <= 114, u64 n <= 290,
 *            u128 n <= 762, big any n
 * Helpers:   flat_push, push_row
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/flat_push.h"
#include "../utils/push_row.h"

/* integer square root of a 64‑bit unsigned integer */
static idx_t isqrt_u64(idx_t v)
{
    idx_t lo = 0, hi = 1;
    /* find an upper bound */
    while ((unsigned __int128)hi * hi <= v) hi <<= 1;
    lo = hi >> 1;
    while (lo < hi) {
        idx_t mid = lo + ((hi - lo + 1) >> 1);
        if ((unsigned __int128)mid * mid <= v)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}

/* main sequence function */
seq_t a(idx_t n)
{
    /* Static state kept between calls */
    static seq_t *prev = NULL;          /* matrix of current length */
    static size_t  prev_stride = 0;     /* stride of the matrix */
    static idx_t   cur_len = 0;         /* length represented by 'prev' matrix */
    static seq_t *flat  = NULL;         /* flattened triangle entries */
    static size_t  flat_size = 0;
    static size_t  flat_cap  = 0;
    static idx_t   max_row_computed = 0;/* highest row fully constructed */

    /* lazy initialization */
    if (cur_len == 0) {
        /* Row 0: T(0,0) = 1 */
        flat_push(&flat, (seq_t)1, &flat_size, &flat_cap);
        /* Prepare DP for length 1 */
        cur_len = 1;
        prev_stride = 1;
        prev = (seq_t *)calloc(prev_stride * prev_stride, sizeof(seq_t));
        prev[0] = (seq_t)1;                 /* sequence [0] */
        /* Store row 1 (k = 0..1) */
        push_row(cur_len, prev, &flat, &flat_size, &flat_cap);
        max_row_computed = 1;
    }

    /* Determine the row number r that contains the n-th flattened entry */
    idx_t r;
    {
        idx_t t = isqrt_u64((idx_t)8 * n + 1);
        r = (t - 1) >> 1;
    }

    /* Grow the triangle until row r is available */
    while (r > max_row_computed) {
        /* Transition from length cur_len to cur_len+1 */
        size_t next_stride = cur_len + 1;
        seq_t *next = (seq_t *)calloc(next_stride * next_stride, sizeof(seq_t));

        for (idx_t asc = 0; asc < cur_len; ++asc) {
            /* Compute total of the current asc row */
            seq_t total = 0;
            for (idx_t last = 0; last < cur_len; ++last) {
                total += prev[asc * prev_stride + last];
            }
            seq_t running = 0;
            idx_t max_y = asc + 1;
            if (max_y >= next_stride) max_y = next_stride - 1;
            for (idx_t y = 0; y <= max_y; ++y) {
                if (y < cur_len) running += prev[asc * prev_stride + y];
                seq_t sum_change = running;
                seq_t sum_no    = total - running;
                /* no new ascent */
                next[asc * next_stride + y] += sum_no;
                /* new ascent: asc count increases */
                next[(asc + 1) * next_stride + y] += sum_change;
            }
        }
        free(prev);
        prev = next;
        prev_stride = next_stride;
        ++cur_len;

        /* Store the new row into the flat array */
        push_row(cur_len, prev, &flat, &flat_size, &flat_cap);
        ++max_row_computed;
    }

    /* Locate the requested entry */
    idx_t offset = r * (r + 1) / 2;
    idx_t col    = n - offset;
    return flat[offset + col];
}
